package protocol

import (
	"encoding/hex"
	"testing"
)

// Aran 21100002 rush movement (live world1, 2026-11-02) carries command 17.
func TestParsePlayerMoveRushCommand(t *testing.T) {
	for i, h := range []string{"", "", "", ""} {
		b, _ := hex.DecodeString(h)
		r := NewReader(b)
		m, err := ParsePlayerMove(r)
		if err != nil || r.Remaining() != 0 || !m.Changed || m.Y < 200 || m.Y > 300 {
			t.Fatalf("frame %d: %+v err=%v remaining=%d", i, m, err, r.Remaining())
		}
	}
}

// The rush lands through command 3: the last frame ends at its position.
func TestParsePlayerMoveRushLanding(t *testing.T) {
	w := NewWriter(RecvMove)
	w.U8(0)
	w.I32(0)
	w.I32(0)
	w.I16(31)
	w.I16(287)
	w.I32(0)
	w.U8(2)
	w.U8(17)
	w.U8(8)
	w.U16(0)
	w.U8(3)
	w.I16(304)
	w.I16(286)
	w.I16(0)
	w.U8(8)
	w.U16(0)
	w.U8(0)
	w.Bytes(make([]byte, 8))
	m, err := ParsePlayerMove(NewReader(w.Packet()[2:]))
	if err != nil || !m.Changed || m.X != 304 || m.Y != 286 {
		t.Fatalf("%+v %v", m, err)
	}
}
